import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String userInput = scanner.nextLine();
        int replacementCount = 0;
        String modifiedString = userInput.replace("at", "@").replace("dot", ".");
        char[] chars = modifiedString.toCharArray();
        int length = chars.length;

        if (length > 0) {
            if (chars[0] == '.') {
                chars[0] = 'd'; // placeholder for 'dot'
            }
            if (chars[length - 1] == '.') {
                chars[length - 1] = 'd'; // placeholder for 'dot'
            }
            if (chars[0] == '@') {
                chars[0] = 'a'; // placeholder for 'at'
            }
            if (chars[length - 1] == '@') {
                chars[length - 1] = 'a'; // placeholder for 'at'
            }
        }

        for (int index = 0; index < length; index++) {
            if (chars[index] == '@' && replacementCount == 0) {
                replacementCount = 1;
            } else if (chars[index] == '@') {
                chars[index] = 'a'; // placeholder for 'at'
            }
            System.out.print(chars[index]);
        }
        scanner.close();
    }
}
